import {ACTUATOR_MODULES} from './actuator-hardware.js';import {CATALOG} from './core.js';
export function actuatorDisplay(c){const m=ACTUATOR_MODULES[c.type],s=CATALOG[c.type].scale;if(c.type==='ws2812')return m.display.pixelCenters.map((p,i)=>`<rect data-rgb-pixel="${c.id}" data-pixel="${i}" x="${(p.x-6)*s}" y="${(p.y-6)*s}" width="${12*s}" height="${12*s}" rx="${2*s}" fill="#1c2330" pointer-events="none"/>`).join('');if(c.type==='stepper28byj')return `<g transform="translate(${m.pivot.x*s} ${m.pivot.y*s})"><g data-stepper-shaft="${c.id}"><path d="M0 0v-14" stroke="#64f2cf" stroke-width="3"/></g></g>`+m.display.coilIndicators.map((p,i)=>`<circle data-stepper-coil="${c.id}" data-coil="${i}" cx="${p.x*s}" cy="${p.y*s}" r="${3*s}" fill="#351923"/>`).join('');return '';}
export function updateActuators(packet){const modules=packet.actuatorDevices?.modules||{};for(const n of document.querySelectorAll('[data-rgb-pixel]')){const d=modules[n.dataset.rgbPixel],rgb=d?.powered?d.frame[+n.dataset.pixel]:[0,0,0];n.setAttribute('fill',rgb?.some(v=>v)?'rgb('+rgb.join(',')+')':'#1c2330');}for(const n of document.querySelectorAll('[data-stepper-shaft]'))n.setAttribute('transform','rotate('+(modules[n.dataset.stepperShaft]?.angle??0)+')');for(const n of document.querySelectorAll('[data-stepper-coil]')){const d=modules[n.dataset.stepperCoil];n.setAttribute('fill',d?.powered&&(d.mask&(1<<(3-Number(n.dataset.coil))))?'#ff4652':'#351923');}}
